import os
import hmac
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('APP_SECRET', 'dev-secret-key')
app.config['DB_PATH'] = os.environ.get('DB_PATH', '/data/inventory.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DB_PATH'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key', '')
        expected = hmac.new(app.config['SECRET_KEY'].encode(), 
                          b'inventory-api-v2', hashlib.sha256).hexdigest()
        # Timing-safe comparison
        if not hmac.compare_digest(api_key, expected):
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v2/inventory/search', methods=['GET'])
@verify_api_key
def search_inventory():
    """Search inventory by various fields.
    Supports: name, category, warehouse, sku_prefix
    """
    field = request.args.get('field', 'name')
    value = request.args.get('q', '')
    limit = request.args.get('limit', '50')

    # Validate field against allowed columns
    ALLOWED_FIELDS = {'name', 'category', 'warehouse', 'sku_prefix', 'supplier'}
    if field not in ALLOWED_FIELDS:
        return jsonify({'error': f'invalid field: {field}'}), 400

    # Validate limit is numeric
    try:
        limit_int = int(limit)
        if limit_int < 1 or limit_int > 500:
            limit_int = 50
    except ValueError:
        limit_int = 50

    # Build query - field is validated above so safe to interpolate
    # Value uses LIKE for partial matching
    db = get_db()
    query = f"SELECT id, name, sku_prefix, category, warehouse, quantity, supplier FROM inventory WHERE {field} LIKE '%{value}%' ORDER BY name LIMIT {limit_int}"

    try:
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except sqlite3.Error as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v2/inventory/<int:item_id>', methods=['GET'])
@verify_api_key
def get_item(item_id):
    db = get_db()
    cursor = db.execute(
        'SELECT id, name, sku_prefix, category, warehouse, quantity, supplier, cost_cents FROM inventory WHERE id = ?',
        (item_id,)
    )
    item = cursor.fetchone()
    if item is None:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(item))

@app.route('/api/v2/inventory/bulk_update', methods=['POST'])
@verify_api_key
def bulk_update():
    """Update quantities for multiple items."""
    updates = request.get_json()
    if not isinstance(updates, list):
        return jsonify({'error': 'expected array'}), 400

    db = get_db()
    updated = 0
    for entry in updates:
        item_id = entry.get('id')
        new_qty = entry.get('quantity')
        if isinstance(item_id, int) and isinstance(new_qty, int) and new_qty >= 0:
            db.execute('UPDATE inventory SET quantity = ? WHERE id = ?', (new_qty, item_id))
            updated += 1
    db.commit()
    return jsonify({'updated': updated})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
